<?php
$pageTitle="Detail Transaksi"; require "header.php";$id=(int)($_GET["id"]??0);
$s=$conn->prepare("SELECT t.*,p.nama_pelanggan FROM tbl_transaksi t LEFT JOIN tbl_pelanggan p ON p.id_pelanggan=t.id_pelanggan WHERE t.id_transaksi=?");$s->bind_param("i",$id);$s->execute();$head=$s->get_result()->fetch_assoc();
$d=$conn->prepare("SELECT d.*,pr.nama_produk FROM tbl_detail_transaksi d JOIN tbl_produk pr ON pr.id_produk=d.id_produk WHERE d.id_transaksi=?");$d->bind_param("i",$id);$d->execute();$details=$d->get_result();
?>
<div class="card"><div class="card-header d-flex justify-content-between"><span>Rincian #<?=e($id)?></span><a href="transaksi.php" class="btn btn-sm btn-outline-secondary">Kembali</a></div><div class="card-body"><?php if($head):?><div class="row mb-3"><div class="col-md-4"><span class="text-muted">Pelanggan</span><div class="fw-semibold"><?=e($head["nama_pelanggan"]??"-")?></div></div><div class="col-md-4"><span class="text-muted">Tanggal</span><div class="fw-semibold"><?=e($head["tanggal"])?></div></div><div class="col-md-4"><span class="text-muted">Total</span><div class="fw-semibold"><?=rupiah($head["total_belanja"])?></div></div></div><div class="table-responsive"><table class="table"><thead><tr><th>Produk</th><th>Jumlah</th><th>Harga</th><th>Subtotal</th></tr></thead><tbody><?php while($r=$details->fetch_assoc()):?><tr><td><?=e($r["nama_produk"])?></td><td><?=e($r["jumlah"])?></td><td><?=rupiah($r["harga"])?></td><td><?=rupiah($r["subtotal"])?></td></tr><?php endwhile;?></tbody></table></div><?php else:?><div class="alert alert-warning">Transaksi tidak ditemukan.</div><?php endif;?></div></div>
<?php require "footer.php"; ?>
